style.css:
@-moz-document domain("youtube.com") {
/* Arka plan düz kırmızımsı ton */
    html {
        background-color: #1a0000 !important;
    }

    /* Ana yapılar için koyu kırmızı ton */
    ytd-app, ytd-page-manager, ytd-watch-flexy, #page-manager {
        background-color: #2b0000 !important;
    }

    /* Üst menü (masthead) */
    ytd-masthead {
        background-color: #3d0000 !important;
    }

    /* Başlıklar ve yazılar */
    yt-formatted-string, h1, h2, h3, a, span {
        color: #ff4d4d !important;
    }

    /* Butonlar */
    ytd-button-renderer, tp-yt-paper-button {
        background-color: #cc0000 !important;
        color: white !important;
        border-radius: 8px !important;
    }

    ytd-button-renderer:hover, tp-yt-paper-button:hover {
        background-color: #ff1a1a !important;
    }

    /* Yorum ve video bilgileri */
    ytd-video-primary-info-renderer,
    ytd-video-secondary-info-renderer,
    #comments {
        background-color: #220000 !important;
    }

    /* Kenar çubuğu */
    #guide-content {
        background-color: #2b0000 !important;
    }

    /* Scroll bar rengi bile kırmızı olsun */
    ::-webkit-scrollbar-thumb {
        background-color: #cc0000 !important;
    }
}
